"""Agrega 'Preguntas frecuentes' a los artículos del lote 1 (idempotente)."""
import os
ROOT=os.path.dirname(os.path.dirname(os.path.abspath(__file__)))
F={
'como-quitar-el-sarro-del-bano':[("¿Puedo usar cloro para el moho de las juntas?","El cloro blanquea, pero nunca lo mezclés con el limpiador de azulejos, vinagre ni otros productos. Usá un solo producto a la vez y enjuagá bien entre uno y otro."),("¿Cada cuánto hay que limpiar el baño a fondo?","Una limpieza profunda de juntas y azulejos una vez por semana evita que el sarro y el moho se acumulen. El resto de los días basta con una limpieza rápida."),("¿El limpiador de azulejos sirve para la cocina?","Sí. El Limpiador de Azulejos León Rojo se usa en azulejos y enchapes de baño y de cocina."),("¿Sirve en mármol?","No apliqués productos para sarro sobre mármol o piedra caliza sin probar primero en una zona escondida; muchos de esos materiales se dañan con productos ácidos.")],
'piscina-verde-que-hacer':[("¿Cuánto tarda en aclararse el agua?","Depende de qué tan verde esté, del tamaño de la piscina y de cuánto trabaje el filtro. Puede tomar desde un día hasta varios días; seguí midiendo y repetí los pasos si hace falta."),("¿Puedo echar el alguicida y el cloro al mismo tiempo?","No los mezclés. Agregá cada producto por separado, directo al agua de la piscina y con el filtro encendido, siguiendo lo que indica cada etiqueta."),("¿Puedo bañarme con el agua verde?","No es recomendable. Esperá a que el agua esté clara y a que pase el tiempo que indica la etiqueta de cada producto."),("¿Qué presentaciones hay?","Algui-Acid en galón; Cloro Granulado en frasco y bolsa de 1 kg; Cloro en Pastilla de 200 g y frasco de 1 kg; Soda Ash en bolsa de 1 kilo.")],
'como-quitar-el-oxido-de-herramientas':[("¿Tengo que lijar hasta que quede brillante?","No. Basta con quitar el óxido suelto y las costras con cepillo de alambre o lija; el desoxidante se encarga del resto según la etiqueta."),("¿Cuánto tiempo puedo esperar para pintar?","Lo mejor es pintar o proteger el metal lo antes posible después de limpiarlo y secarlo, para que no vuelva a oxidarse."),("¿Sirve para portones y verjas?","Sí, para herramientas, piezas y superficies metálicas. En piezas grandes trabajá por secciones."),("¿En qué presentaciones viene?","En 1/2 litro, litro y galón.")],
'como-eliminar-el-comejen-de-la-madera':[("¿El preservante sirve en madera ya pintada?","Necesita penetrar en la madera, así que funciona sobre madera limpia, seca y sin pintura ni barniz. Si la madera ya está pintada, consultá la etiqueta o escribinos."),("¿Qué preservante uso para una casa de madera?","El Pentacell, soluble en agua, está indicado para casas de madera, vigas y cercas."),("¿Se puede usar dentro de la casa?","Seguí siempre lo que dice la etiqueta, aplicalo con buena ventilación y no lo uses en utensilios de cocina, comederos ni bebederos."),("¿Si ya hay mucho daño, el preservante lo arregla?","No. El preservante protege la madera, pero no recupera la que ya está comida. Si hay daño estructural, consultá con un profesional.")],
'como-limpiar-aros-de-aluminio':[("¿Sirve para aros cromados o pintados?","El ALUX-500 es para aluminio. No lo apliqués sobre pintura ni vidrio; si tus aros tienen otro acabado, consultanos antes."),("¿Lo uso directo o diluido?","Depende del trabajo: la etiqueta indica cuándo se usa directo y cuándo diluido."),("¿Sirve para cajones de camión y tanques?","Sí, para aros, perfiles, cajones de camión y tanques de aluminio."),("¿En qué presentaciones viene?","En litro repuesto, litro atomizador y galón.")],
'como-quitar-manchas-de-aceite-del-piso':[("¿Las manchas viejas salen del todo?","Las manchas recientes salen mucho mejor. En manchas de años, repetir el proceso las aclara bastante, aunque a veces queda una sombra porque el aceite penetró en el concreto."),("¿Puedo usar el desengrasante en el motor del carro?","Sí, está hecho para motores, piezas y pisos de taller. Te lo explicamos en nuestra guía para limpiar el motor."),("¿Qué uso para lavar todo el taller?","Para áreas grandes como talleres, aceras y patios, el Detergente en Polvo Industrial León Rojo, que viene desde 1 kg hasta 25 kg."),("¿El desengrasante se diluye?","Sí, se puede diluir según el trabajo. La proporción para cada uso viene en la etiqueta.")],
'como-reparar-goteras-del-techo':[("¿Puedo aplicar el tapagoteras con lluvia?","No. La superficie tiene que estar limpia y completamente seca."),("¿Sirve en canoas?","Sí, para techos, canoas y uniones de lámina."),("¿Y si la lámina está muy oxidada y con muchos huecos?","El tapagoteras es para reparar puntos. Si la lámina está muy deteriorada, lo correcto es cambiarla."),("¿En qué presentaciones viene?","En 1/16, 1/8 y 1/4 de galón.")],
'que-no-mezclar-con-cloro':[("¿Puedo usar vinagre y cloro el mismo día?","Sí, pero nunca juntos ni uno encima del otro sin enjuagar. Usá uno, enjuagá bien con agua, ventilá y luego usá el otro en otra limpieza."),("¿Mezclar cloro con detergente es peligroso?","Muchos detergentes contienen ingredientes que no deben mezclarse con cloro. Lo más seguro es no mezclarlos y seguir la etiqueta de cada producto."),("¿Qué hago si un niño tomó un producto de limpieza?","No provoqués el vómito. Llamá al Centro Nacional de Control de Intoxicaciones al 2223-1028 o al 911 y tené a mano el envase del producto."),("¿Cuál cloro uso en la casa?","El Cloro León Rojo doméstico al 3% o 4%. El de 12% es industrial y requiere más cuidado al manipularlo.")],
'como-desinfectar-corrales-y-establos':[("¿Creolina o Desinfectante: cuál uso?","La Creolina es para corrales, establos, desagües y áreas exteriores. El Desinfectante sirve para viviendas, plantas empacadoras, lecherías y áreas en general, y además deja aroma."),("¿Se pueden diluir?","Sí. La proporción para cada uso viene en la etiqueta de cada producto."),("¿Puedo aplicarlo con los animales adentro?","No. Retirá a los animales, limpiá, desinfectá y dejá secar y ventilar antes de que vuelvan, según la etiqueta."),("¿En qué presentaciones viene la Creolina?","En 240 ml, 1/2 litro, litro y galón.")],
'llantas-negras-y-brillantes':[("¿Puedo aplicarlo en la llanta mojada?","Es mejor sobre la llanta limpia y seca, así el producto se distribuye parejo y dura más."),("¿Se aplica en los aros?","No, se aplica en el hule de la llanta. Para aros de aluminio está el ALUX-500."),("¿Cuál es la diferencia entre el 80 y el 1000?","El Llantilux-80 es para uso diario; el Llantilux-1000 es la versión de alto poder para lavacar y detallado profesional."),("¿En qué presentaciones vienen?","Los dos en litro y galón.")],
'como-pulir-y-encerar-el-carro':[("¿Cada cuánto hay que encerar el carro?","Depende de cuánto sol y lluvia reciba y de cómo se lave. Cuando el agua deja de formar gotas sobre la pintura, es señal de que toca encerar de nuevo."),("¿El polish quita rayones?","Quita microarañazos y la capa opaca. Un rayón profundo que llegó a la base o al metal necesita trabajo de pintura."),("¿Cera en pasta o cera líquida?","La líquida, en atomizador, es más rápida; la de pasta deja una capa más trabajada. Las dos dan brillo y protección."),("¿Puedo pulir al sol?","No. Trabajá a la sombra y con la pintura fría para que el producto no se seque y manche.")],
'thinner-aguarras-o-espiritu-mineral':[("¿Puedo usar thinner en pintura de aceite?","El thinner NC es para lacas nitrocelulosa. Para pintura de aceite se usa aguarrás o espíritu mineral, según indique el fabricante de la pintura."),("¿Con qué limpio la pistola de pintar?","Después de trabajar con lacas, con Thinner Industrial NC: hacé pasar thinner limpio hasta que salga sin color."),("¿El canfín sirve para diluir pintura?","No. El canfín (keroseno) se usa para encendido, lámparas y limpieza de piezas."),("¿En qué presentaciones vienen?","Thinner, aguarrás y espíritu mineral en 1/2 litro, litro y galón; el canfín en 1/2 litro, litro y galón.")],
}
import html as H
for s,qs in F.items():
    p=os.path.join(ROOT,'posts',s+'.html'); t=open(p,encoding='utf-8').read()
    if 'Preguntas frecuentes' in t: continue
    t=t.rstrip()+'\n<h2>Preguntas frecuentes</h2>\n'+''.join(f'<h3>{H.escape(q)}</h3><p>{H.escape(a)}</p>\n' for q,a in qs)
    open(p,'w',encoding='utf-8').write(t)
print('ok')
